module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Complemented outputs for the AND and OR gates
    wire q0_n, q1_n, q2_n;
    assign q0_n = ~q0;
    assign q1_n = ~q1;
    assign q2_n = ~q2;

    // D flip-flops with synchronous reset (initial value 0)
    always @(posedge clk) begin
        // q0: D input is XOR of x and its own previous output q0
        q0 <= x ^ q0;

        // q1: D input is AND of x and complemented previous output q1_n
        q1 <= x & q1_n;

        // q2: D input is OR of x and complemented previous output q2_n
        q2 <= x | q2_n;
    end

    // Three-input NOR gate: output is Z
    // NOR(a, b, c) = ~(a | b | c)
    assign z = ~(q0 | q1 | q2);

endmodule

