module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 3 bits are sufficient for 5 states
    typedef enum logic [2:0] {
        S_IDLE   = 3'b000,
        S_1      = 3'b001,
        S_11     = 3'b010,
        S_110    = 3'b011,
        S_1101   = 3'b100
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            S_IDLE: begin
                if (data == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end
            S_1: begin
                if (data == 1'b1)
                    next_state = S_11;
                else
                    next_state = S_IDLE;
            end
            S_11: begin
                if (data == 1'b0)
                    next_state = S_110;
                else
                    next_state = S_11; // stay on another '1'
            end
            S_110: begin
                if (data == 1'b1)
                    next_state = S_1101;
                else
                    next_state = S_IDLE;
            end
            S_1101: begin
                // Once the sequence is detected, stay in this state
                next_state = S_1101;
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Output logic
    // start_shifting is 1 when the sequence 1101 has been found
    assign start_shifting = (state == S_1101);

endmodule

