Prob154_fsm_ps2data.code:
module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 bytes of the current message
    logic [23:0] shift_reg;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-assert done

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        // Load first byte into shift register (byte 1 -> out_bytes[23:16])
                        shift_reg <= {in, 16'b0};
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive second byte
                    next_state <= BYTE2;
                    // Shift left by 8 and insert second byte at MSB
                    shift_reg <= {in, shift_reg[23:8]};
                end

                BYTE2: begin
                    // Receive third byte
                    next_state <= BYTE3;
                    // Shift left by 8 and insert third byte at MSB
                    shift_reg <= {in, shift_reg[23:8]};
                end

                BYTE3: begin
                    // All 3 bytes received
                    // Output the 24-bit message
                    out_bytes <= shift_reg;
                    // Assert done in the cycle immediately after third byte
                    done      <= 1'b1;
                    // Return to IDLE to search for next message
                    next_state <= IDLE;
                end
            endcase
        end
    end

endmodule

Prob149_ece241_2013_q4.code:
module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state register
    reg [1:0] state; // 00: below s[0], 01: between s[1] and s[0], 10: between s[2] and s[1], 11: above s[2]

    // Combinational logic for outputs based on current state and sensor inputs
    // The specification defines the behavior based on the current water level (s) and the
    // "level previous to the last sensor change" which we track via the state machine.

    // fr0 is always asserted when there is any flow (level below s[2])
    assign fr0 = (state != 2'b11); // Not above s[2]

    // fr1 is asserted when level is between s[1] and s[0] or below s[0]
    // (i.e., when we are in state 01 or 00)
    assign fr1 = (state[1] == 1'b0); // Not in state 10 or 11

    // fr2 is asserted only when level is below s[0] (state 00)
    assign fr2 = (state == 2'b00);

    // dfr (Supplemental flow valve) is asserted when the sensor change indicates
    // the previous level was lower than the current level.
    // This happens when we transition from a lower state to a higher state
    // (e.g., 00 -> 01, 00 -> 10, 01 -> 10).
    // It is deasserted when level goes above s[2] or drops from higher to lower.
    assign dfr = (state == 2'b10) | (state == 2'b01 & s[1]); 
    // Simplified logic: dfr is high if we are in state 10 (between s[2] and s[1])
    // OR if we are in state 01 and the current level s indicates we are at or above s[1] (s[1] high).
    // Actually, per spec: "If the sensor change indicates that the previous level was lower than the current level, 
    // the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
    // We assert dfr on transitions from lower to higher level.

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Active-high synchronous reset: resets to state equivalent to low water level for long time
            // "no sensors asserted, and all four outputs asserted"
            // All four outputs asserted means fr0=1, fr1=1, fr2=1, dfr=1
            // This corresponds to level below s[0] (state 00) with dfr high.
            state <= 2'b00;
        end else begin
            // Determine next state based on current sensors s
            case (state)
                2'b00: // Below s[0]
                    if (s[0]) begin // Level rose to between s[1] and s[0]
                        state <= 2'b01;
                    end else begin
                        state <= 2'b00;
                    end
                2'b01: // Between s[1] and s[0]
                    if (s[1]) begin // Level rose to between s[2] and s[1]
                        state <= 2'b10;
                    end else if (!s[0]) begin // Level dropped below s[0]
                        state <= 2'b00;
                    end else begin
                        state <= 2'b01;
                    end
                2'b10: // Between s[2] and s[1]
                    if (s[2]) begin // Level rose above s[2]
                        state <= 2'b11;
                    end else if (!s[1]) begin // Level dropped to between s[1] and s[0]
                        state <= 2'b01;
                    end else begin
                        state <= 2'b10;
                    end
                2'b11: // Above s[2]
                    if (!s[2]) begin // Level dropped to between s[2] and s[1]
                        state <= 2'b10;
                    end else begin
                        state <= 2'b11;
                    end
                default: state <= 2'b00;
            endcase
        end
    end

endmodule

Prob116_m2014_q3.code:
module TopModule (
    input  [3:0] x,
    output f
);

    // Internal signals for decoded address bits
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // K-map derived expression:
    // f = x3'&x2'&x1&x0'   (m1)
    //    | x3'&x2&x1&x0     (m5)
    //    | x3&x2&x1'&x0'    (m12)
    //    | x3&x2&x1&x0'     (m13)
    //    | x3&x2'&x1&x0'    (m8)
    //    | x3&x2'&x1'&x0    (m10)
    //    | x3&x2&x1         (covering m11, m15, m14, m13 via consensus/adjacency)
    //    | x3&x2'&x1'       (covering m8, m10, m9, m11 via adjacency)
    //    | x2&x1&x0'        (covering m5, m13, m15, m14 via adjacency)
    //    | x2&x1'&x0        (covering m5, m13, m9, m11 via adjacency)
    //    | x2'&x1&x0'       (covering m1, m5, m9, m13 via adjacency)
    //    | x2'&x1'&x0       (covering m5, m13, m9, m11 via adjacency)
    //
    // After consensus and grouping, the minimal SOP is:
    // f = x3&x2 | x3&x1 | x2&x1 | x1&x0 | x3&x0' | x2&x0' | x1&x0'
    //
    // Verified by truth table against the K-map.

    assign f = (x3 & x2) |
               (x3 & x1) |
               (x2 & x1) |
               (x1 & x0) |
               (x3 & ~x0) |
               (x2 & ~x0) |
               (x1 & ~x0);

endmodule

