module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 3 bits
    // State A: 3'b000
    // State B: 3'b001
    // State C: 3'b010
    // State D: 3'b011
    // State E: 3'b100
    // State F: 3'b101
    // State G: 3'b110
    // State H: 3'b111

    reg [2:0] state, next_state;

    // Output logic (Moore machine: outputs depend only on state)
    assign f = (state == 3'b001);  // f = 1 in state B
    assign g = (state == 3'b110);  // g = 1 in state G

    // State register (positive edge triggered, synchronous active low reset)
    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= 3'b000;  // State A
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic
    always @(*) begin
        case (state)
            3'b000: begin // State A: idle, reset asserted or initial
                next_state = 3'b000;
            end
            3'b001: begin // State B: f is 1 for one cycle
                next_state = 3'b010; // Go to State C
            end
            3'b010: begin // State C: monitor x for pattern 1,0,1
                if (x == 1'b1) begin
                    next_state = 3'b011; // State D: saw first 1
                end else begin
                    next_state = 3'b010; // Stay in State C
                end
            end
            3'b011: begin // State D: saw 1, now waiting for 0
                if (x == 1'b0) begin
                    next_state = 3'b100; // State E: saw 1,0
                end else begin
                    next_state = 3'b011; // Stay in State D (x was 1, reset pattern)
                end
            end
            3'b100: begin // State E: saw 1,0, now waiting for 1
                if (x == 1'b1) begin
                    next_state = 3'b101; // State F: pattern 1,0,1 complete
                end else begin
                    next_state = 3'b010; // Reset monitoring, go back to State C
                end
            end
            3'b101: begin // State F: pattern 1,0,1 complete, set g=1, go to State G
                next_state = 3'b110; // State G
            end
            3'b110: begin // State G: g=1, monitor y for "1 within 2 cycles"
                if (y == 1'b1) begin
                    next_state = 3'b110; // y=1 received, stay in State G (permanent)
                end else begin
                    // Check if this is the first or second cycle without y=1
                    // We need to count cycles. Since we only have one bit y,
                    // we use the state to implicitly count.
                    // If we stay in State G and y remains 0, we must eventually
                    // transition to State H after two cycles.
                    // To implement the "within at most two clock cycles" requirement,
                    // we transition to State H after two consecutive cycles of y=0.
                    // We can achieve this by having two sub-states or by checking
                    // the pattern. Here we use a simple counter-like approach:
                    // If we are in State G and y=0, we move to a state that
                    // expects the next cycle. If that next cycle also has y=0,
                    // we go to H.
                    // We will encode this with additional states if needed,
                    // but to keep it within the 3-bit encoding spirit, we can
                    // use the existing states creatively or add states.
                    // Since 3 bits give 8 states, and we have used 7 (A-H),
                    // we have State H (3'b111) available.
                    // Let's re-map or use State H for the timeout.
                    // Actually, let's use State G for "y=1 seen" and a new
                    // implicit count. Since we can't easily count with one bit
                    // without extra states, let's define:
                    // State G: y=1 seen or waiting first cycle.
                    // But the spec says: "While maintaining g=1 the FSM has to monitor the y input.
                    // If y has the value 1 within at most two clock cycles, then the FSM should
                    // maintain g=1 permanently... But if y does not become 1 within two clock cycles,
                    // then the FSM should set g=0 permanently".
                    // This implies we need to count two cycles of y=0.
                    // Let's use State G, State I, State J or reuse.
                    // Given we have 8 states (0-7), and used A(000) to G(110),
                    // we have H(111) left. That's only one state.
                    // We need to distinguish "first cycle y=0" and "second cycle y=0".
                    // Therefore, we need at least 2 extra states.
                    // Let's redefine the state encoding to have enough states.
                    // Original encoding used 8 states for A-H. That was 8 states.
                    // A:000, B:001, C:010, D:011, E:100, F:101, G:110, H:111.
                    // We have exactly 8 states. We used A-G (7 states). H is free.
                    // We need to count 0, 1, 2 cycles. That requires 3 states for the counter
                    // (or 2 states if we use the output g status, but g is already 1).
                    // Actually, we can use the transition from G.
                    // Let's add states I and J by overloading or extending.
                    // Since the prompt asks for a module, and Icarus Verilog g2012,
                    // I can use more bits or get creative.
                    // Let's stick to the 3-bit encoding but use the states for counting.
                    // State G (110): g=1, y might be 1 or 0. If y=1, stay G.
                    // If y=0, go to State I (which we don't have).
                    // Let's redefine the state machine to use 4 bits or specific transitions.
                    // Actually, the spec says "within at most two clock cycles".
                    // This means: At cycle N, if y=1, ok. At cycle N+1, if y=1, ok.
                    // At cycle N+2, if y still 0, fail.
                    // So from the moment g becomes 1 (entering State G), we have two cycles
                    // to see a y=1.
                    // If we see y=1 in the first cycle after entering G, stay in G.
                    // If we see y=0 in the first cycle, we move to a "waiting for y=1" state.
                    // If in that state we see y=1, go back to G.
                    // If we see y=0 again, go to g=0 state.
                    // Since we have 3 bits, we have 8 states. We used 7. We can use H(111)
