            3'b111: begin // State H: g=1, second cycle of y monitoring
                if (y == 1'b1) begin
                    next_state = 3'b110; // State G: y=1 seen, maintain g=1
                end else begin
                    next_state = 3'b000; // State A: y=0 for two cycles, set g=0
                end
            end
            default: next_state = 3'b000;
        endcase
    end

