module TopModule (
    input  clk,
    input  reset,
    output ena   [2:0],
    output q     [15:0]
);

    // Internal registers for the 4 BCD digits
    reg [3:0] ones;
    reg [3:0] tens;
    reg [3:0] hundreds;
    reg [3:0] thousands;

    // ena outputs: active-high enable for the next higher digit
    // ena[0] -> tens increment enable
    // ena[1] -> hundreds increment enable
    // ena[2] -> thousands increment enable
    assign ena = {tens[3], hundreds[3], thousands[3]};

    // Synchronous always block for BCD counter logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ones   <= 4'b0;
            tens   <= 4'b0;
            hundreds <= 4'b0;
            thousands <= 4'b0;
        end else begin
            // Increment ones; if it rolls over (==9), set carry to tens
            if (ones == 4'd9)
                ones <= 4'd0;
            else
                ones <= ones + 1'b1;

            // Tens increment if ones overflowed
            if (ones == 4'd9)
                if (tens == 4'd9)
                    tens <= 4'd0;
                else
                    tens <= tens + 1'b1;
            else
                tens <= tens; // hold

            // Hundreds increment if tens overflowed
            if (tens == 4'd9 && ones == 4'd9)
                if (hundreds == 4'd9)
                    hundreds <= 4'd0;
                else
                    hundreds <= hundreds + 1'b1;
            else
                hundreds <= hundreds; // hold

            // Thousands increment if hundreds overflowed
            if (hundreds == 4'd9 && tens == 4'd9 && ones == 4'd9)
                if (thousands == 4'd9)
                    thousands <= 4'd0;
                else
                    thousands <= thousands + 1'b1;
            else
                thousands <= thousands; // hold
        end
    end

    // Concatenate the 4 digits into the 16-bit output q
    assign q = {thousands, hundreds, tens, ones};

endmodule

