module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        WALK_LEFT,    // 000
        WALK_RIGHT,   // 001
        FALLING,      // 010
        DIGGING,      // 011
        SPLATTERED    // 100
    } state_t;

    state_t state, next_state;

    // Fall counter - counts cycles spent falling
    logic [4:0] fall_counter;

    // Saved direction before fall/dig
    state_t saved_dir;

    // Outputs (Moore machine)
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register with fall counter and saved dir update
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            fall_counter <= 0;
            saved_dir <= WALK_LEFT;
        end else begin
            state <= next_state;

            // Update fall counter and saved dir based on new state
            case (next_state)
                WALK_LEFT, WALK_RIGHT: begin
                    // Resuming walk - saved_dir might be used later
                    fall_counter <= 0;
                    // saved_dir preserved for potential future fall
                end
                FALLING: begin
                    fall_counter <= 1;
                    saved_dir <= state; // Save current walking direction before fall
                end
                DIGGING: begin
                    fall_counter <= 0;
                    // saved_dir preserved - was set before dig started
                end
                SPLATTERED: begin
                    fall_counter <= 0;
                end
            endcase
        end
    end

    // Next-state logic
    always_comb begin
        next_state = state; // Default: stay in current state

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Ground disappeared -> fall
                    next_state = FALLING;
                end else if (dig) begin
                    // Start digging
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    // Switch direction if bumped
                    if (bump_left && bump_right) begin
                        // Both bumps -> still switch direction
                        next_state = WALK_RIGHT;
                    end else if (bump_left) begin
                        // Bumped on left -> walk right
                        next_state = WALK_RIGHT;
                    end else if (bump_right) begin
                        // Bumped on right -> walk left (but we're already walking left)
                        // Spec: "if it's bumped on the right, it will walk left"
                        // If already walking left and bumped right, should we switch?
                        // Spec says it will walk left - we're already going left, so stay
                        next_state = WALK_LEFT;
                    end
                end
                // If none apply, stay WALK_LEFT
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    if (bump_left && bump_right) begin
                        next_state = WALK_LEFT;
                    end else if (bump_left) begin
                        // Bumped on left while walking right -> switch to left
                        next_state = WALK_LEFT;
                    end else if (bump_right) begin
                        // Bumped on right while walking right -> switch to left
                        // Spec: "if it's bumped on the right, it will walk left"
                        next_state = WALK_LEFT;
                    end
                end
            end

            FALLING: begin
                if (ground) begin
                    // Ground reappeared
                    if (fall_counter > 20) begin
                        // Fell for more than 20 cycles -> splatter
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in saved direction
                        next_state = saved_dir;
                    end
                end else begin
                    // Ground still absent, keep falling
                    // Counter will increment in state register
                end
                // Being bumped while falling has no effect
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached other side while digging -> fall
                    next_state = FALLING;
                    // saved_dir is already set from before dig started
                end else begin
                    // Still on ground
                    if (!dig) begin
                        // Stop digging, resume walking in saved direction
                        next_state = saved_dir;
                    end
                    // If dig=1, keep digging (next_state stays DIGGING)
                end
            end

            SPLATTERED: begin
                // Forever stuck, no transitions
            end
        endcase
    end

endmodule

